using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using ProMaxx2.QA.Domain.Identity;using ProMaxx2.QA.Domain.Projects;using ProMaxx2.QA.Domain.Releases;using ProMaxx2.QA.Domain.Requirements;
namespace ProMaxx2.QA.Infrastructure.Persistence;
public sealed class RequirementConfiguration:IEntityTypeConfiguration<Requirement>{public void Configure(EntityTypeBuilder<Requirement>b){b.ToTable("Requirements");b.HasKey(x=>x.RequirementId);b.Property(x=>x.RequirementId).HasDefaultValueSql("NEWSEQUENTIALID()");b.Property(x=>x.RequirementCode).HasMaxLength(100).IsRequired();b.HasIndex(x=>new{x.ProjectId,x.RequirementCode}).IsUnique();b.Property(x=>x.Title).HasMaxLength(300).IsRequired();b.Property(x=>x.Priority).HasMaxLength(20).IsRequired();b.Property(x=>x.RiskLevel).HasMaxLength(20);b.Property(x=>x.Source).HasMaxLength(200);b.Property(x=>x.Status).HasMaxLength(30).IsRequired();b.Property(x=>x.CreatedAt).HasPrecision(0);b.Property(x=>x.UpdatedAt).HasPrecision(0);b.HasOne<Project>().WithMany().HasForeignKey(x=>x.ProjectId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Release>().WithMany().HasForeignKey(x=>x.ReleaseId).OnDelete(DeleteBehavior.Restrict);b.HasOne<ProductModule>().WithMany().HasForeignKey(x=>x.ModuleId).OnDelete(DeleteBehavior.Restrict);b.HasOne<User>().WithMany().HasForeignKey(x=>x.OwnerUserId).OnDelete(DeleteBehavior.Restrict);}}
public sealed class RequirementRevisionConfiguration:IEntityTypeConfiguration<RequirementRevision>{public void Configure(EntityTypeBuilder<RequirementRevision>b){b.ToTable("RequirementRevisions");b.HasKey(x=>x.RequirementRevisionId);b.Property(x=>x.RequirementRevisionId).HasDefaultValueSql("NEWSEQUENTIALID()");b.HasIndex(x=>new{x.RequirementId,x.RevisionNo}).IsUnique();b.Property(x=>x.Title).HasMaxLength(300).IsRequired();b.Property(x=>x.ChangeReason).HasMaxLength(1000);b.Property(x=>x.ChangedAt).HasPrecision(0);b.HasOne(x=>x.Requirement).WithMany(x=>x.Revisions).HasForeignKey(x=>x.RequirementId).OnDelete(DeleteBehavior.Cascade);b.HasOne<User>().WithMany().HasForeignKey(x=>x.ChangedBy).OnDelete(DeleteBehavior.Restrict);}}
